create trigger PREINS_WCM
on R5WARCOMPONENTS
instead of insert
as
	declare @sSysUser		nvarchar(38)
	declare @sPk         	nvarchar(30)        
	declare @sWarranty   	nvarchar(30)        
	declare @sSyslevel   	nvarchar(30)        
	declare @sAsmlevel   	nvarchar(30)        
	declare @sComplevel  	nvarchar(30)        
	declare @nSqlidentity	integer       
	declare @nReturn		integer      
	declare @sChk1			nvarchar(4)
    declare @dUpdated       datetime

    declare @sReansonforrepair 		nvarchar(4);
	declare @sWorkaccomplished 		nvarchar(4);
	declare @sUsecostcoveragevalues nvarchar(1);
	declare	@nLaborcharge			numeric(5,2);
	declare @nHiredlaborcharge		numeric(5,2);
	declare @nServicecharge			numeric(5,2);
	declare @nStockitemscharge		numeric(5,2);
	declare @nDirectpurchasecharge	numeric(5,2);
	declare @nToolcharge			numeric(5,2);
	declare @nFixedlaborrate		numeric(24,6);
	declare @nFixedlaboramount		numeric(24,6);
	declare @nFixedstockamount		numeric(24,6);
	declare @nMaxlaboramount		numeric(24,6);
	declare @nMaxstockamount		numeric(24,6);

	if @@ROWCOUNT > 0
		begin
			SET NOCOUNT ON
			declare c_inserted cursor local for select	WCM_PK,	WCM_WARRANTY,	WCM_SYSLEVEL,	WCM_ASMLEVEL,	WCM_COMPLEVEL,
													  	WCM_SQLIDENTITY, WCM_UPDATED,
													  	WCM_REANSONFORREPAIR, WCM_WORKACCOMPLISHED, WCM_USECOSTCOVERAGEVALUES, 
														WCM_LABORCHARGE, WCM_HIREDLABORCHARGE, WCM_SERVICECHARGE, WCM_STOCKITEMSCHARGE, 
														WCM_DIRECTPURCHASECHARGE, WCM_TOOLCHARGE, WCM_FIXEDLABORRATE, WCM_FIXEDLABORAMOUNT, 
														WCM_FIXEDSTOCKAMOUNT, WCM_MAXLABORAMOUNT, WCM_MAXSTOCKAMOUNT
													from inserted
			set @sSysUser = dbo.O7GTSUSR()
			open c_inserted
			fetch next from c_inserted into 	@sPk,	@sWarranty,	@sSyslevel,	@sAsmlevel,	@sComplevel,
												@nSqlidentity, @dUpdated,
												@sReansonforrepair, @sWorkaccomplished, @sUsecostcoveragevalues,  
												@nLaborcharge, @nHiredlaborcharge, @nServicecharge, @nStockitemscharge, 
												@nDirectpurchasecharge,	@nToolcharge, @nFixedlaborrate, @nFixedlaboramount, 
												@nFixedstockamount, @nMaxlaboramount,	@nMaxstockamount
			while @@FETCH_STATUS = 0
				begin
					if @sSysUser <> N'SYS'
						begin
							execute @nReturn = R5O7_O7MAXSEQ @sPk OUTPUT, N'WCM', N'1', @sChk1 OUTPUT
							if @@ERROR <> 0 or @nReturn <> 0 
								begin
									close c_inserted
									deallocate c_inserted
									rollback transaction
									return
								end

						end
					insert into R5WARCOMPONENTS(	WCM_PK,	WCM_WARRANTY,	WCM_SYSLEVEL,	WCM_ASMLEVEL,	WCM_COMPLEVEL, WCM_UPDATED,
													WCM_REANSONFORREPAIR, WCM_WORKACCOMPLISHED, WCM_USECOSTCOVERAGEVALUES, 
													WCM_LABORCHARGE, WCM_HIREDLABORCHARGE, WCM_SERVICECHARGE, WCM_STOCKITEMSCHARGE, 
													WCM_DIRECTPURCHASECHARGE, WCM_TOOLCHARGE, WCM_FIXEDLABORRATE, WCM_FIXEDLABORAMOUNT, 
													WCM_FIXEDSTOCKAMOUNT, WCM_MAXLABORAMOUNT, WCM_MAXSTOCKAMOUNT)
								values (	@sPk,	@sWarranty,	@sSyslevel,	@sAsmlevel,	@sComplevel, @dUpdated,
											@sReansonforrepair, @sWorkaccomplished, @sUsecostcoveragevalues,
											@nLaborcharge, @nHiredlaborcharge, @nServicecharge, @nStockitemscharge,
											@nDirectpurchasecharge,	@nToolcharge, @nFixedlaborrate, @nFixedlaboramount,
											@nFixedstockamount, @nMaxlaboramount,	@nMaxstockamount)

					fetch next from c_inserted into 	@sPk,	@sWarranty,	@sSyslevel,	@sAsmlevel,	@sComplevel,
														@nSqlidentity, @dUpdated,
														@sReansonforrepair, @sWorkaccomplished, @sUsecostcoveragevalues,
														@nLaborcharge, @nHiredlaborcharge, @nServicecharge, @nStockitemscharge,
														@nDirectpurchasecharge,	@nToolcharge, @nFixedlaborrate, @nFixedlaboramount,
														@nFixedstockamount, @nMaxlaboramount,	@nMaxstockamount
				end
			close c_inserted
			deallocate c_inserted
		end


